from functools import lru_cache

class Solution:
    def maxHappyGroups(self, batchSize: int, groups: List[int]) -> int:
        freq = [0] * batchSize
        base = 0
        for g in groups:
            if g % batchSize == 0:
                base += 1
            else:
                freq[g % batchSize] += 1

        @lru_cache(maxsize=None)
        def dfs(counts, rem):
            best = 0
            for i in range(1, batchSize):
                if counts[i]:
                    nxt = list(counts)
                    nxt[i] -= 1
                    best = max(best, dfs(tuple(nxt), (rem + i) % batchSize)
                               + (1 if rem == 0 else 0))
            return best

        return base + dfs(tuple(freq), 0)

