#include <functional>
#include <map>
#include <vector>

class Solution {
public:
    int maxHappyGroups(int batchSize, vector<int>& groups) {
        vector<int> freq(batchSize);
        int base = 0;
        for (int g : groups) {
            if (g % batchSize == 0) base++;
            else freq[g % batchSize]++;
        }
        map<pair<vector<int>, int>, int> memo;
        function<int(vector<int>, int)> dfs =
            [&](vector<int> cnt, int rem) -> int {
            auto it = memo.find({cnt, rem});
            if (it != memo.end()) return it->second;
            int best = 0;
            for (int i = 1; i < batchSize; i++) {
                if (cnt[i] > 0) {
                    cnt[i]--;
                    best = max(best, dfs(cnt, (rem + i) % batchSize)
                                     + (rem == 0 ? 1 : 0));
                    cnt[i]++;
                }
            }
            return memo[{cnt, rem}] = best;
        };
        return base + dfs(freq, 0);
    }
};

