import java.util.*;

class Solution {
    private int b;
    private Map<Long, Integer> memo = new HashMap<>();

    public int maxHappyGroups(int batchSize, int[] groups) {
        b = batchSize;
        int[] freq = new int[b];
        int base = 0;
        for (int g : groups) {
            if (g % b == 0) base++;
            else freq[g % b]++;
        }
        return base + dfs(freq, 0);
    }

    private int dfs(int[] freq, int rem) {
        long key = rem;
        for (int i = 1; i < b; i++) key |= (long) freq[i] << (4 + 6 * (i - 1));
        Integer cached = memo.get(key);
        if (cached != null) return cached;
        int best = 0;
        for (int i = 1; i < b; i++) {
            if (freq[i] > 0) {
                freq[i]--;
                best = Math.max(best, dfs(freq, (rem + i) % b) + (rem == 0 ? 1 : 0));
                freq[i]++;
            }
        }
        memo.put(key, best);
        return best;
    }
}

