        ans = 0
        for g in groups:
            freq[g % batchSize] += 1
        ans += freq[0]
        for r in range(1, batchSize // 2 + 1):
            if r * 2 == batchSize:
                ans += freq[r] // 2
                freq[r] %= 2
            else:
                k = min(freq[r], freq[batchSize - r])
                ans += k
                freq[r] -= k
                freq[batchSize - r] -= k

        @lru_cache(maxsize=None)
        def dfs(counts, rem):
            best = 0
            for i in range(1, batchSize):
                if counts[i]:
                    nxt = list(counts)
                    nxt[i] -= 1
                    best = max(best, dfs(tuple(nxt), (rem + i) % batchSize)
                               + (1 if rem == 0 else 0))
            return best

        return ans + dfs(tuple(freq), 0)

